import{_ as a,c as n,o,ag as r}from"./chunks/framework.DQvKz0xt.js";const f=JSON.parse('{"title":"约束类型 (Constraint Types) - Rive 编辑器","description":"约束 (Constraints) Rive 提供了多种约束类型，用于控制对象之间的关系。每种约束都有其特定的用途和配置选项。","frontmatter":{"title":"约束类型 (Constraint Types) - Rive 编辑器","description":"约束 (Constraints) Rive 提供了多种约束类型，用于控制对象之间的关系。每种约束都有其特定的用途和配置选项。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 约束, 约束类型"}]]},"headers":[],"relativePath":"editor/constraints/types.md","filePath":"editor/constraints/types.md","lastUpdated":1774838907000}'),i={name:"editor/constraints/types.md"};function s(e,t,c,l,d,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<p>约束 (Constraints)</p><h1 id="约束类型-constraint-types" tabindex="-1">约束类型 (Constraint Types) <a class="header-anchor" href="#约束类型-constraint-types" aria-label="Permalink to &quot;约束类型 (Constraint Types)&quot;">​</a></h1><p>Rive 提供了多种约束类型，用于控制对象之间的关系。每种约束都有其特定的用途和配置选项。</p><h2 id="​-可用的约束类型" tabindex="-1"><a href="#available-constraints">​</a> 可用的约束类型 <a class="header-anchor" href="#​-可用的约束类型" aria-label="Permalink to &quot;[​](#available-constraints) 可用的约束类型&quot;">​</a></h2><h3 id="ik-约束-ik-constraint" tabindex="-1"><a href="/docs/editor/constraints/ik-constraint">IK 约束 (IK Constraint)</a> <a class="header-anchor" href="#ik-约束-ik-constraint" aria-label="Permalink to &quot;[IK 约束 (IK Constraint)](/editor/constraints/ik-constraint.md)&quot;">​</a></h3><p>反向动力学约束。通过在骨骼链末端放置目标点，系统自动计算父级骨骼的旋转角度。常用于角色的手臂、腿部动画，让脚&quot;踩&quot;在地面上或让手指向某个物体。</p><h3 id="距离约束-distance-constraint" tabindex="-1"><a href="/docs/editor/constraints/distance-constraint">距离约束 (Distance Constraint)</a> <a class="header-anchor" href="#距离约束-distance-constraint" aria-label="Permalink to &quot;[距离约束 (Distance Constraint)](/editor/constraints/distance-constraint.md)&quot;">​</a></h3><p>限制两个对象之间的距离。可以设置最小距离（防止过近）、最大距离（防止过远）或固定距离（保持恒定间隔）。</p><h3 id="位移约束-translation-constraint" tabindex="-1"><a href="/docs/editor/constraints/translation-constraint">位移约束 (Translation Constraint)</a> <a class="header-anchor" href="#位移约束-translation-constraint" aria-label="Permalink to &quot;[位移约束 (Translation Constraint)](/editor/constraints/translation-constraint.md)&quot;">​</a></h3><p>让一个对象跟随另一个对象的位置移动。可以单独控制 X 轴、Y 轴或两者的跟随行为。</p><h3 id="旋转约束-rotation-constraint" tabindex="-1"><a href="/docs/editor/constraints/rotation-constraint">旋转约束 (Rotation Constraint)</a> <a class="header-anchor" href="#旋转约束-rotation-constraint" aria-label="Permalink to &quot;[旋转约束 (Rotation Constraint)](/editor/constraints/rotation-constraint.md)&quot;">​</a></h3><p>让一个对象跟随另一个对象的旋转角度。常用于让多个齿轮同步转动或让眼睛跟随目标。</p><h3 id="缩放约束-scale-constraint" tabindex="-1"><a href="/docs/editor/constraints/scale-constraint">缩放约束 (Scale Constraint)</a> <a class="header-anchor" href="#缩放约束-scale-constraint" aria-label="Permalink to &quot;[缩放约束 (Scale Constraint)](/editor/constraints/scale-constraint.md)&quot;">​</a></h3><p>让一个对象跟随另一个对象的缩放比例。可以实现联动缩放效果。</p><h3 id="变换约束-transform-constraint" tabindex="-1"><a href="/docs/editor/constraints/transform-constraint">变换约束 (Transform Constraint)</a> <a class="header-anchor" href="#变换约束-transform-constraint" aria-label="Permalink to &quot;[变换约束 (Transform Constraint)](/editor/constraints/transform-constraint.md)&quot;">​</a></h3><p>综合约束，同时复制目标对象的位移、旋转和缩放。让一个对象完全镜像另一个对象的所有变换属性。</p><h3 id="路径跟随约束-follow-path-constraint" tabindex="-1"><a href="/docs/editor/constraints/follow-path-constraint">路径跟随约束 (Follow Path Constraint)</a> <a class="header-anchor" href="#路径跟随约束-follow-path-constraint" aria-label="Permalink to &quot;[路径跟随约束 (Follow Path Constraint)](/editor/constraints/follow-path-constraint.md)&quot;">​</a></h3><p>让对象沿着一条路径移动。非常适合创建沿轨道运动的动画，如过山车、行星轨道或自定义运动路径。</p><h3 id="滚动约束-scroll-constraint" tabindex="-1"><a href="/docs/editor/constraints/scroll-constraint">滚动约束 (Scroll Constraint)</a> <a class="header-anchor" href="#滚动约束-scroll-constraint" aria-label="Permalink to &quot;[滚动约束 (Scroll Constraint)](/editor/constraints/scroll-constraint.md)&quot;">​</a></h3><p>专为布局 (Layout) 对象设计的特殊约束，允许其子元素进行滚动。支持构建可滚动内容区域和滚动条。</p><hr><h2 id="​-通用属性" tabindex="-1"><a href="#common-properties">​</a> 通用属性 <a class="header-anchor" href="#​-通用属性" aria-label="Permalink to &quot;[​](#common-properties) 通用属性&quot;">​</a></h2><p>所有约束都共享一些通用属性：</p><ul><li><strong>强度 (Strength)</strong>：控制约束的影响程度（0% = 无影响，100% = 完全影响）。可以设置动画来平滑地启用/禁用约束或混合多个约束。</li><li><strong>目标 (Target)</strong>：指定约束参照的对象。</li><li><strong>约束顺序</strong>：当一个对象有多个约束时，顺序会影响最终结果。可以拖放来调整顺序。</li></ul><p><a href="/docs/editor/constraints/overview">约束概览 (Overview)</a><a href="/docs/editor/constraints/ik-constraint">IK 约束 (IK Constraint)</a></p>',25)])])}const m=a(i,[["render",s]]);export{f as __pageData,m as default};
